// app/app/session-api.js — the ONE definition of where the Discord/wallet session service lives.
//
// This used to be the string 'https://api.degener.us', repeated in four modules (discord-link,
// profiles, records, player-target). That host was a separate Fly app; it was destroyed with the
// rest of the hosted infrastructure, and the service now runs as a Cloudflare Pages Function on
// THIS origin (website/functions/session/[[path]].js) over D1.
//
// ⭐ Same origin is not just tidier, it removes a class of bug the old code had to work around.
// Cross-site cookies from api.degener.us needed SameSite=None, so the OAuth popup's top-level
// cookie and the app's fetch cookies could land in different jars — Safari/ITP especially. That
// is why discord-link.js carries a one-use `discordLinkToken` ticket and a comment explaining
// that /auth/discord/me may disagree with /api/player. On one origin the cookie is SameSite=Lax
// and both see the same session; the ticket is kept as belt-and-braces through the redirect.
//
// A relative base also means localhost talks to a local `wrangler pages dev`, and the deployed
// site talks to itself, with no per-environment switch.
export const SESSION_API = '/session';
